import 'package:latlong2/latlong.dart';

import 'poi.dart';

/// A suggested rest stop generated by [TripBreakPlanner]: a point along
/// the route, roughly [timeIntoTrip] into the drive, where more than
/// one useful category (fuel, food, restroom, ...) is available within
/// a short distance of each other - a single stop worth planning
/// around, rather than three separate searches.
class ComboStop {
  final LatLng location;
  final Duration timeIntoTrip;

  /// The single closest point of interest at this stop - used as its
  /// name/marker, and as the place actually added to the route when
  /// the user taps "Add stop".
  final Poi anchor;

  /// One [Poi] per distinct category found nearby (including [anchor]).
  final List<Poi> nearbyByCategory;

  const ComboStop({
    required this.location,
    required this.timeIntoTrip,
    required this.anchor,
    required this.nearbyByCategory,
  });

  List<String> get categories => nearbyByCategory.map((p) => p.category).toList();

  String get timeIntoTripLabel {
    final totalMinutes = timeIntoTrip.inMinutes;
    final hours = totalMinutes ~/ 60;
    final minutes = totalMinutes % 60;
    if (hours == 0) return '~$minutes min in';
    if (minutes == 0) return '~${hours}h in';
    return '~${hours}h ${minutes}min in';
  }
}
